### 1. إعداد قاعدة البيانات (SQL)
يجب عليك تنفيذ هذا الكود في **Supabase SQL Editor**:

```sql
create table patristic_chats (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  title text,
  messages jsonb,
  updated_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- تفعيل الحماية
alter table patristic_chats enable row level security;

-- السماح للمستخدمين بإدارة محادثاتهم
create policy "Users can manage own chats" on patristic_chats
  for all using (auth.uid() = user_id);
```

