function App() {
  // Auth State
  const [user, setUser] = useState<any>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [showIntro, setShowIntro] = useState(true);
  const [selectedTool, setSelectedTool] = useState<ToolId | null>(null);

