        ];
        break;

      case 'bible':
        steps = [
          { element: '#bible-nav', popover: { title: 'التنقل السريع', description: 'تنقل بين العهدين، الأسفار، والأصحاحات بسهولة وسرعة.', side: 'bottom' } },
          { element: '#bible-toolbar', popover: { title: 'أدوات القراءة', description: 'تحكم في حجم الخط، نوع الخط، ووضع التركيز (Focus Mode) لقراءة خاشعة بدون تشتيت.', side: 'bottom' } },
          { element: '#study-tools-panel', popover: { title: 'ترسانة الدارس', description: 'بضغطة واحدة: احصل على تفسير عميق للأصحاح، أو شرح مبسط للأطفال، أو تحليل لغوي للكلمات الأصلية.', side: 'top' } },
          { element: '#verse-interaction', popover: { title: 'تفاعل مع الآيات', description: 'اضغط على أي آية لتحديدها، وسيظهر لك شريط أدوات خاص لنسخها أو تفسيرها بشكل منفرد.', side: 'top' } }
        ];
        break;
    }

    driverObj.current = driver({
      showProgress: true,
      animate: true,
      allowClose: true,
      nextBtnText: 'التالي',
      prevBtnText: 'السابق',
      doneBtnText: 'فهمت، شكراً',
      progressText: '{{current}} من {{total}}',
      steps: steps,
      popoverClass: 'driverjs-theme'
    });

    driverObj.current.drive();
  };

  return { startTour };
};
