        return (
            <div className={containerClasses}>
                <div id="bible-toolbar" className={`sticky top-0 bg-[#0f172a]/95 backdrop-blur-md z-40 py-4 rounded-b-xl shadow-lg ${isFocusMode ? 'max-w-4xl mx-auto' : ''}`}>
                    {/* Reading Toolbar */}
                    <div className="flex items-center justify-between border-b border-white/10 pb-4 px-2">
                        <div className="flex items-center gap-1 sm:gap-2">
