                    </div>
                 </div>
            )}

            {view === 'testament-select' && <TestamentSelect />}
            {view === 'book-select' && <BookSelect />}
            {view === 'chapter-select' && <ChapterSelect />}
            {view === 'reading' && <ReadingView />}
        </div>
    );
};

