  };
  const handleOpenExplanation = () => { /* ... */ };

  const renderContent = () => {
      if (!showIntro && !selectedTool) {
          // Pass User to ToolsDashboard
          return <ToolsDashboard onSelectTool={setSelectedTool} user={user} />;
      }

      if (selectedTool === 'lesson-builder') {
