                    <BookOpenIcon className="w-8 h-8 text-amber-500" />
                    <h1 className="text-4xl font-bold text-white font-serif drop-shadow-lg">الكتاب المقدس</h1>
                </div>
             )}

            <Breadcrumb />

            {error && !isFocusMode && (
                 <div className="w-full max-w-lg mx-auto mb-8 animate-fade-in-down">
