import { GoogleGenAI, Type } from "@google/genai";
import type { LessonPlan, Idea, IdeaSection, AgeGroup, ChatMessage } from '../types';
// ... (Previous code)

export async function generateLessonCampaign(objective: string, weeks: number): Promise<any> {
    try {
        const schema = {
            type: Type.OBJECT,
            properties: {
                title: { type: Type.STRING, description: "Title of the entire campaign" },
                description: { type: Type.STRING, description: "Brief description of the campaign theme" },
                lessons: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            week: { type: Type.INTEGER },
                            title: { type: Type.STRING },
                            verse: { type: Type.STRING },
                            concept: { type: Type.STRING, description: "The core concept/link to the main objective" },
                            brief: { type: Type.STRING, description: "Short summary of the lesson content" }
                        },
                        required: ["week", "title", "verse", "concept", "brief"]
                    }
                }
            },
            required: ["title", "description", "lessons"]
        };

        const prompt = `
            Create a Sunday School lesson campaign (series) consisting of ${weeks} lessons.
            Spiritual Objective: "${objective}".

            The campaign must be cohesive, where each lesson builds upon the previous one to achieve the main objective.
            Language: Arabic.
            Target Audience: General Sunday School (adaptable).
        `;

        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: schema,
                temperature: 0.8
            }
        });

        const responseText = response.text;
        const json = JSON.parse(responseText || "{}");
        return json;
    } catch (error) {
        console.error("Error generating lesson campaign:", error);
        throw new Error("فشل في توليد حملة الدروس. حاول مرة أخرى.");
    }
}

