import React, { useState } from 'react';
import { TargetIcon, CalendarIcon, PlayCircleIcon, LightBulbIcon } from './icons';
import { useAppTour } from '../hooks/useAppTour';
import SmartAutoComplete from './SmartAutoComplete';

interface LessonCampaignFormProps {
    onSubmit: (objective: string, weeks: number) => void;
    isLoading: boolean;
}

const LessonCampaignForm: React.FC<LessonCampaignFormProps> = ({ onSubmit, isLoading }) => {
    const { startTour } = useAppTour();
    const [objective, setObjective] = useState('');
    const [weeks, setWeeks] = useState(4); // Default to 4 weeks

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (objective.trim()) {
            onSubmit(objective, weeks);
        }
    };

    return (
        <div className="w-full max-w-3xl mx-auto animate-fade-in-up relative">
             {/* Tour Button */}
             <button 
                onClick={() => startTour('lesson-campaign-builder' as any)} // Cast to any to avoid type error until TourType is updated
                className="absolute top-0 left-0 md:left-0 flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/10 hover:bg-purple-500/20 text-slate-300 hover:text-white border border-white/10 hover:border-purple-500/50 transition-all text-xs font-bold backdrop-blur-sm z-10"
            >
                <PlayCircleIcon className="w-4 h-4 text-purple-400" />
                <span>جولة تعليمية</span>
            </button>

            <div className="text-center mb-10">
                <h2 className="text-4xl font-bold text-white mb-4 drop-shadow-md font-serif">
                    بناء حملة دروس
                </h2>
                <p className="text-lg text-white/90 font-medium drop-shadow">
                    سلسلة دروس مترابطة تخدم هدفاً روحياً واحداً
                </p>
            </div>

            <div className="glass-card p-6 md:p-10 rounded-3xl shadow-2xl border border-purple-500/30 bg-gradient-to-b from-purple-900/20 to-[#0f172a]/60 backdrop-blur-md">
                <form onSubmit={handleSubmit} className="space-y-6">

                    {/* Spiritual Objective */}
                    <div>
                        <div className="flex items-center gap-2 mb-2">
                            <TargetIcon className="w-5 h-5 text-purple-400" />
                            <label className="spark-h3 text-white">الهدف الروحي للحملة</label>
                        </div>
                        <SmartAutoComplete
                            id="campaign-objective"
                            type="objective"
                            value={objective}
                            onChange={(e) => setObjective(e.target.value)}
                            placeholder="مثال: تعليم الأطفال أهمية الصلاة، أو حياة القديس بولس الرسول..."
                            className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-white placeholder-slate-500 focus:ring-2 focus:ring-purple-400 focus:border-purple-400 transition-all text-right"
                            required
                            minLength={10}
                            isTextarea={true}
                            rows={2}
                        />
                         <p className="text-xs text-slate-400 mt-1 mr-1">سيتم تصميم جميع الدروس لتخدم هذا الهدف بشكل متسلسل.</p>
                    </div>

                    {/* Number of Weeks */}
                    <div>
                        <div className="flex items-center gap-2 mb-2">
                            <CalendarIcon className="w-5 h-5 text-purple-400" />
                            <label className="spark-h3 text-white">مدة الحملة (عدد الأسابيع)</label>
                        </div>
                         <div className="flex items-center gap-4">
                            <input 
                                type="range" 
                                min="2" 
                                max="8" 
                                value={weeks} 
                                onChange={(e) => setWeeks(parseInt(e.target.value))}
                                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-500"
                            />
                            <span className="text-white font-bold text-xl min-w-[3rem] text-center bg-white/10 rounded-lg py-1 px-2 border border-white/10">
                                {weeks}
                            </span>
                        </div>
                        <p className="text-xs text-slate-400 mt-1 mr-1">اختر من 2 إلى 8 أسابيع.</p>
                    </div>

                    <button
                        id="campaign-submit-btn"
                        type="submit"
                        disabled={isLoading || !objective.trim()}
                        className="w-full text-white font-bold text-lg py-4 px-6 rounded-xl bg-gradient-to-r from-purple-600 to-purple-500 hover:from-purple-500 hover:to-purple-400 transition-all shadow-lg hover:shadow-purple-500/20 disabled:opacity-50 flex items-center justify-center gap-2 transform hover:scale-[1.01]"
                    >
                         <LightBulbIcon className="w-6 h-6" />
                        {isLoading ? 'جاري بناء الحملة...' : 'توليد الحملة'}
                    </button>
                </form>
            </div>
        </div>
    );
};

