## smart-loading.js

Create the logic to simulate realistic loading steps and remove the overlay when done.

```javascript
(function() {
    // Configuration
    const overlay = document.getElementById('loading-overlay');
    const progressBar = document.getElementById('loader-bar');
    const percentageText = document.getElementById('loader-percent');
    const stageText = document.getElementById('loader-stage');
    const messageText = document.getElementById('loader-message');

    let currentProgress = 0;
    const messages = [
        "انت الخادم الحقيقي انا بس بساعدك",
        "الدرس هيبقى من غير روح لو انت محضرتوش بنفسك",
        "أنا مجرد أداة، والروح القدس هو المعلم",
        "كل كلمة بتكتبها بتبني نفوس",
        "التحضير الجيد هو صلاة قبل ما يكون قراءة"
    ];

    // Message Rotator
    let msgIndex = 0;
    setInterval(() => {
        msgIndex = (msgIndex + 1) % messages.length;
        if(messageText) {
            messageText.style.opacity = 0;
            setTimeout(() => {
                messageText.innerText = `"${messages[msgIndex]}"`;
                messageText.style.opacity = 1;
            }, 500);
        }
    }, 2500);

    // Update UI Function
    const updateUI = (progress, stage) => {
        currentProgress = progress;
        if(progressBar) progressBar.style.width = `${progress}%`;
        if(percentageText) percentageText.innerText = `${Math.round(progress)}%`;
        if(stageText && stage) stageText.innerText = stage;
    };

    // Simulation Logic
    const startLoading = async () => {
        const steps = [
            { label: "تحميل ملفات التنسيق...", target: 15, duration: 400 },
            { label: "تهيئة بيئة العمل...", target: 35, duration: 600 },
            { label: "الاتصال بقاعدة البيانات...", target: 55, duration: 800 },
            { label: "جلب محتوى الكتاب المقدس...", target: 75, duration: 800 },
            { label: "تجهيز الواجهة الرسومية...", target: 90, duration: 600 },
            { label: "اكتمل التحميل!", target: 100, duration: 400 }
        ];

        for (const step of steps) {
            updateUI(currentProgress, step.label);

            const start = currentProgress;
            const end = step.target;
            const stepDuration = step.duration;
            const frames = 20; 

            for(let i = 0; i <= frames; i++) {
                const nextVal = start + ((end - start) * (i / frames));
                updateUI(nextVal);
                await new Promise(r => setTimeout(r, stepDuration / frames));
            }
        }

        // Finish
        setTimeout(() => {
            if(overlay) {
                overlay.classList.add('hidden');
                setTimeout(() => overlay.remove(), 800); // Remove from DOM
            }
        }, 500);
    };

    // Start immediately
    if (document.readyState === 'complete') {
        startLoading();
    } else {
        window.addEventListener('load', startLoading);
    }
})();
