// Helper function for delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Robust retry wrapper for API calls
async function retryOperation<T>(operation: () => Promise<T>, retries = 3, backoff = 2000): Promise<T> {
    try {
        return await operation();
    } catch (error: any) {
        // Check for Rate Limit (429) or Service Unavailable (503)
        if (retries > 0 && (error.status === 429 || error.status === 503 || error.message?.includes('429'))) {
            console.warn(`Rate limit hit. Retrying in ${backoff}ms... (${retries} retries left)`);
            await delay(backoff);
            // Exponential backoff: double the wait time each retry
            return retryOperation(operation, retries - 1, backoff * 2);
        }
        throw error;
    }
}

